+package cmd
+
+import (
+	"context"
+	"crypto/rand"
+	"crypto/rsa"
+	"crypto/x509"
+	"encoding/pem"
+	"os"
+	"path/filepath"
+	"testing"
+
+	"github.com/stretchr/testify/require"
+	"go.flipt.io/flipt/internal/config"
+	"go.uber.org/zap/zaptest"
+)
+
+func TestAuthenticationGRPCJWTWithoutDatabase(t *testing.T) {
+	privateKey, err := rsa.GenerateKey(rand.Reader, 2048)
+	require.NoError(t, err)
+	publicKey, err := x509.MarshalPKIXPublicKey(&privateKey.PublicKey)
+	require.NoError(t, err)
+	keyPath := filepath.Join(t.TempDir(), "jwt-public.pem")
+	require.NoError(t, os.WriteFile(keyPath, pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: publicKey}), 0600))
+
+	cfg := &config.Config{}
+	cfg.Storage.Type = config.LocalStorageType
+	cfg.Database.URL = "invalid://database"
+	cfg.Authentication.Required = true
+	cfg.Authentication.Methods.JWT.Enabled = true
+	cfg.Authentication.Methods.JWT.Method.PublicKeyFile = keyPath
+
+	register, interceptors, shutdown, err := authenticationGRPC(context.Background(), zaptest.NewLogger(t), cfg, false, false)
+	require.NoError(t, err)
+	require.Len(t, register, 2)
+	require.Len(t, interceptors, 3) // JWT, client token, and required authentication.
+	require.NoError(t, shutdown(context.Background()))
+}
